('formal_proposals','f92ef348-76ae-4ee0-b25a-cd1532a20ee7','issuer_logo_id','7ee39632-74ea-4fee-a3cb-c028e87cecfc','bc7674ce-d1a7-42ed-abcc-f2f079bf34de','crm-legacy-logo:7ee39632-74ea-4fee-a3cb-c028e87cecfc:bc7674ce-d1a7-42ed-abcc-f2f079bf34de'),
('formal_proposals','fe82e4ed-5037-4969-94de-dffcc4a40597','issuer_logo_id','b0e92d15-2e87-4c1a-93ac-3399bf8fe515','52e3d239-9e0b-4789-ad87-86d4a357e8d6','crm-legacy-logo:b0e92d15-2e87-4c1a-93ac-3399bf8fe515:52e3d239-9e0b-4789-ad87-86d4a357e8d6')),
projected_formal AS (
 SELECT f.*,coalesce(f.tenant_id,m.tenant_id) AS effective_tenant
 FROM formal_proposals f LEFT JOIN formal_manifest m ON m.document_id=f.proposal_doc_id
), actual_refs AS (
 SELECT 'formal_proposals'::text AS parent_table,proposal_doc_id AS parent_id,'issuer_logo_id'::text AS field,effective_tenant AS tenant_id,issuer_logo_id AS logo_id FROM projected_formal
 UNION ALL SELECT 'formal_proposals',proposal_doc_id,'client_logo_id',effective_tenant,client_logo_id FROM projected_formal
 UNION ALL SELECT 'clients',client_id,'client_logo_id',tenant_id,client_logo_id FROM clients
), checks AS (
 SELECT 'formal_manifest.mismatch' AS check_name,count(*)::bigint AS violations
 FROM formal_manifest m LEFT JOIN formal_proposals f ON f.proposal_doc_id=m.document_id
 LEFT JOIN quotes q ON q.quote_id=m.quote_id LEFT JOIN tenants t ON t.tenant_id=m.tenant_id
 WHERE f.proposal_doc_id IS NULL OR q.quote_id IS NULL OR t.tenant_id IS NULL
 OR f.quote_id IS DISTINCT FROM m.quote_id OR f.proposal_id IS NOT NULL
 OR q.tenant_id IS DISTINCT FROM m.tenant_id
 OR (f.tenant_id IS NOT NULL AND f.tenant_id IS DISTINCT FROM m.tenant_id)
 UNION ALL SELECT 'formal_null.unlisted',count(*) FROM formal_proposals f
 WHERE f.tenant_id IS NULL AND NOT EXISTS(SELECT 1 FROM formal_manifest m WHERE m.document_id=f.proposal_doc_id)
 UNION ALL SELECT 'logo_sources.mismatch',count(*) FROM copy_manifest m
 LEFT JOIN company_logos s ON s.logo_id=m.source_id LEFT JOIN tenants t ON t.tenant_id=m.tenant_id
 WHERE s.logo_id IS NULL OR s.tenant_id IS NOT NULL OR t.tenant_id IS NULL OR md5(to_jsonb(s)::text) IS DISTINCT FROM m.source_hash
 UNION ALL SELECT 'logo_copies.mismatch',count(*) FROM copy_manifest m
 JOIN company_logos c ON c.logo_id=m.copy_id LEFT JOIN company_logos s ON s.logo_id=m.source_id
 WHERE s.logo_id IS NULL OR to_jsonb(c) IS DISTINCT FROM
 (to_jsonb(s)||jsonb_build_object('logo_id',m.copy_id,'tenant_id',m.tenant_id,'is_default',false))
 UNION ALL SELECT 'logo_references.mismatch',count(*) FROM ref_manifest m LEFT JOIN actual_refs r
 ON r.parent_table=m.parent_table AND r.parent_id=m.parent_id AND r.field=m.field
 WHERE r.parent_id IS NULL OR r.tenant_id IS DISTINCT FROM m.tenant_id
 OR r.logo_id IS NULL OR r.logo_id NOT IN (m.source_id,m.copy_id)
 UNION ALL SELECT 'global_logo_references.unlisted',count(*) FROM actual_refs r
 JOIN tenants t ON t.tenant_id=r.tenant_id JOIN company_logos l ON l.logo_id=r.logo_id
 WHERE l.tenant_id IS NULL AND NOT EXISTS(SELECT 1 FROM ref_manifest m
 WHERE m.parent_table=r.parent_table AND m.parent_id=r.parent_id AND m.field=r.field
 AND m.tenant_id=r.tenant_id AND m.source_id=r.logo_id)
 UNION ALL SELECT 'known_parent_foreign_logo.mismatch',count(*) FROM actual_refs r
 JOIN tenants t ON t.tenant_id=r.tenant_id JOIN company_logos l ON l.logo_id=r.logo_id
 WHERE l.tenant_id IS NOT NULL AND l.tenant_id IS DISTINCT FROM r.tenant_id
)
SELECT now() AS checked_at,check_name,violations FROM checks ORDER BY check_name;
